def E(name, brief, params=None, returns=None, note=None, see=None, warning=None, **kw):
    d = {"name": name, "brief": brief}
    if params: d["params"] = params
    if returns: d["returns"] = returns
    if note: d["note"] = note
    if warning: d["warning"] = warning
    if see: d["see"] = see
    d.update(kw)
    return d

N = {"n": "the number to compare with, a number or a number written as text"}
TF = "TRUE or FALSE"
E_ = []

# --- the sizes: Double, Triple ... of n -------------------------------------
for nm, w in [("Double", "twice"), ("Triple", "three times"), ("Quadruple", "four times"), ("Quintuple", "five times"),
              ("Sextuple", "six times"), ("Octuple", "eight times"), ("Nonuple", "nine times"), ("Decuple", "ten times")]:
    E_.append(E("Is%sOf" % nm, "TRUE if the number is %s n." % w, params=N, returns=TF, see=["IsMultipleOf"]))

# --- Always TRUE / Always FALSE: a number answers for the kinds it is not --------
for nm, ans, why in [
    ("IsAString", "FALSE", "a number is not a string"), ("IsNotAString", "TRUE", "a number is not a string"),
    ("IsAList", "FALSE", "a number is not a list"), ("IsNotAList", "TRUE", "a number is not a list"),
    ("IsNamedObject", "FALSE", "a plain number carries no name"), ("IsNotANumber", "FALSE", "this is a number"),
    ("IsALetter", "FALSE", "a number is not a letter"), ("IsItem", "TRUE", "a number can be an item of a list"),
    ("IsMember", "TRUE", "a number can be a member of a list"), ("IsAObject", "TRUE", "the wrapper is an object"),
    ("IsAnObject", "TRUE", "the wrapper is an object"), ("IsNotAnObject", "FALSE", "the wrapper is an object"),
    ("IsStzNumber", "TRUE", "the object is a stzNumber"), ("ContainsDigits", "TRUE", "a number is made of digits")]:
    E_.append(E(nm, "Answers %s, because %s." % (ans, why), returns=ans))
for nm, ans in [("IsALetterOf", "FALSE"), ("IsACharOf", "FALSE"), ("IsCharOf", "FALSE"), ("IsLetterOf", "FALSE"),
                ("IsACharIn", "FALSE"), ("IsALetterIn", "FALSE"), ("IsCharIn", "FALSE"), ("IsLetterIn", "FALSE")]:
    E_.append(E(nm, "Answers FALSE for any text, because a number is not a character or a letter.", params={"pcStr": "the text, ignored", "pStrOrListOfChars": "the text or list of characters, ignored"}, returns="FALSE"))

# --- the scale words: does the number reach hundreds, thousands ... ---------------
for nm, lim in [("ContainsSeveralHundreds", "200"), ("ContainsSeveralThousands", "2,000"), ("ContainsSeveralMillions", "2,000,000"),
                ("ContainsSeveralBillions", "2,000,000,000"), ("ContainsSeveralTrillions", "2 trillion"),
                ("ContainsTensOfThousands", "10,000"), ("ContainsTensOfMillions", "10,000,000"), ("ContainsTensOfBillions", "10 billion"),
                ("ContainsTensOfTrillions", "10 trillion"), ("ContainsHundredsOfThousands", "100,000"),
                ("ContainsHundredsOfMillions", "100,000,000"), ("ContainsHundredsOfBillions", "100 billion"),
                ("ContainsHundredsOfTrillions", "100 trillion"), ("ContainsDozens", "10"), ("HasHundreds", "100"),
                ("HasThousands", "1,000"), ("HasMillions", "1,000,000"), ("HasBillions", "1 billion"), ("HasTrillions", "1 trillion"),
                ("HasManyTensOfBillions", "20 billion")]:
    E_.append(E(nm, "TRUE if the number is at least %s." % lim, returns=TF))

# --- the digits at a scale ------------------------------------------------------
for part, w in [("Units", "units"), ("Dozens", "tens"), ("Hundreds", "hundreds")]:
    for sc, s in [("Hundreds", "last group of three digits"), ("Thousands", "thousands group"), ("Millions", "millions group"),
                  ("Billions", "billions group"), ("Trillions", "trillions group")]:
        if part == "Hundreds" and sc == "Hundreds":
            continue
        E_.append(E("%sIn%s" % (part, sc), "Returns the %s digit of the %s of the integer part, as text." % (w, s), returns="a one-digit string; empty when the group is absent", see=["Structure"]))
for nm, w in [("AllUnits", "units"), ("AllDozens", "tens"), ("AllHundreds", "hundreds")]:
    E_.append(E(nm, "Returns the %s digit of every group of three digits, as [ scale, digit ] pairs." % w, returns="a list of [ name, text ] pairs: inhundreds, inthousands, inmillions, inbillions, intrillions", see=["Structure"]))

